/**
 * Exposes a value from a TSX host without putting JSX in the runnable fence.
 *
 * **Example** (Run a TypeScript fence from a TSX host)
 *
 * ```ts import.meta.vitest name="Run a TypeScript fence from a TSX host"
 * 2 + 2 // => 4
 * ```
 *
 * @category utilities
 * @since 0.0.0
 */
export const valueFromTsxHost = 4;
